import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        final long MOD = 1000000007;

        if (k != 1 && k != 0) {
            boolean[] used = new boolean[(int)p];
            for (int i = 0; i < p; i++) {
                used[i] = true;
            }

            long total = 1;
            for (long start = 1; start < p; start++) {
                if (used[(int)start]) {
                    long current = start;
                    do {
                        current = (current * k) % p;
                        used[(int)current] = false;
                    } while (current != start);
                    total = (total * p) % MOD;
                }
            }
            System.out.println(total);
        } else if (k == 1) {
            long product = 1;
            for (long i = 0; i < p; i++) {
                product = (product * p) % MOD;
            }
            System.out.println(product);
        } else {
            long product = 1;
            for (long i = 0; i < p - 1; i++) {
                product = (product * p) % MOD;
            }
            System.out.println(product);
        }
        scanner.close();
    }
}
